template.css:
.status-indicator {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 8px;
}
.indicator-light {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid #333;
  background: #444;
  box-shadow: inset 0 0 5px rgba(0,0,0,0.5);
  transition: all 0.3s;
}
.indicator-light.on {
  background: #00ff88;
  box-shadow: 0 0 15px #00ff88, inset 0 0 5px rgba(255,255,255,0.5);
  border-color: #00ff88;
}
.indicator-light.off {
  background: #444;
  border-color: #333;
}
.indicator-light.alarm {
  background: #ff0044;
  box-shadow: 0 0 15px #ff0044, inset 0 0 5px rgba(255,255,255,0.5);
  border-color: #ff0044;
  animation: blink 1s infinite;
}
.indicator-light.warn {
  background: #ffaa00;
  box-shadow: 0 0 15px #ffaa00, inset 0 0 5px rgba(255,255,255,0.5);
  border-color: #ffaa00;
}
@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}
.indicator-label {
  color: #00ff88;
  font-size: 14px;
  font-weight: bold;
}

template.js:
function initStatusIndicator(element, config) {
  const light = element.querySelector('.indicator-light');

  function updateState(value) {
    light.className = 'indicator-light';

    if (config.stateMap) {
      const state = config.stateMap[value] || 'off';
      light.classList.add(state);
    } else if (typeof value === 'boolean') {
      light.classList.add(value ? 'on' : 'off');
    } else {
      light.classList.add(value);
    }
  }

  return { updateState };
}
